var findMaxSum = function(nums1, nums2, k) {
    let dict = {};
    let dict_index = {};
    let n = nums1.length;

    for (let i=0; i<n; i++)
    {
        dict[nums1[i]] = nums2[i];
        dict_index[nums1[i]] = i;
    }
    let result_index = [];
    for (let key in dict_index)
    {
        result_index.push(dict_index[key]);
    }
    console.log(dict);
    console.log(dict_index);
    let nums = [];
    for (let key in dict)
    {
        nums.push(dict[key]);
    }
    console.log(nums);
    console.log("####");

    
    let result = [];
    for (let i=0; i<n; i++)
    {

        let values = [];
        let trickleUp = function()
        {
            let index = values.length - 1;
            let data = values[index];

            while (index > 0 )
            {
                let parentIndex = Math.floor((index-1)/2);
                let parent = values[parentIndex];

                if (data < parent)
                {
                    break;
                }
                values[index] = values[parentIndex];
                index = parentIndex;
            }
            values[index] = data;
        }

        let trickleDown = function(index)
        {
            let data = values[index];
            let largeIndex;

            while (index < values.length/2)
            {
                let leftIndex = 2*index + 1;
                let rightIndex = 2*index + 2;

                if (rightIndex<values.length && values[rightIndex]>values[leftIndex])
                {
                    largeIndex = rightIndex;
                }
                else
                {
                    largeIndex = leftIndex;
                }
                if (values[largeIndex]==undefined || data>values[largeIndex])
                {
                    break;
                }
                values[index] = values[largeIndex];
                index = largeIndex;
            }
            values[index] = data;
        }

        // console.log(nums.slice(0,i));
        let arr = nums.slice(0,i);
        if (arr.length == 0)
        {
            result.push(0);
            
        }
        else if (arr.length == 1)
        {
            result.push(arr[0]);
        }
        else
        {
            for (let item of arr)
            {
                values.push(item);
                trickleUp();
            }
            let total = 0;
            for (let i=0; i<k; i++)
            {
                
                total = total + values[0];
                values[0] = values[values.length-1];
                trickleDown(0);
                values.pop();
            }
            result.push(total);
            // console.log(values);
        }
    }
    console.log(result_index);
    console.log("@@@");
    console.log(result);

    let dict_result = {};
    for (let i=0; i<n; i++)
    {
        dict_result[result_index[i]] = result[i];
    }
    console.log(dict_result);

    let final_result = [];
    for (let key in dict_result)
    {
        final_result.push(dict_result[key]);
    }
    return final_result;
};

